ost": "identifie"}, {"fe": "FE-103", "fam": "Piperaceae", "nom": "Liane cordée", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-103.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-104", "fam": "Rutaceae", "nom": "Composée à pellucides (curry?)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-104.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-105", "fam": "Phyllanthaceae", "nom": "Phyllanthus", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-105.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-106", "fam": "Lamiaceae", "nom": "Vitex (palmée-composée)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-106.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-107", "fam": "Asphodelaceae", "nom": "Aloe (succulente)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-107.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-108", "fam": "Cucurbitaceae", "nom": "Cucurbitacée (vrille)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-108.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-109", "fam": "À confirmer", "nom": "Liane à vrille", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-109.jpg", "named": false, "ost": "a_identifier"}, {"fe": "FE-110", "fam": "Polygonaceae", "nom": "Renouée (herbacée)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-110.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-111", "fam": "Euphorbiaceae", "nom": "Acalypha (feuillage rouge)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-111.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-112", "fam": "Fougère (Polypodiopsida)", "nom": "Fougère (sores linéaires)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-112.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-113", "fam": "À confirmer", "nom": "Plante très poilue", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-113.jpg", "named": false, "ost": "a_identifier"}, {"fe": "FE-114", "fam": "Urticaceae", "nom": "Feuille dentée (ortie?)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-114.jpg", "named": true, "ost": "identifie"}, {"fe": "FE-115", "fam": "À confirmer", "nom": "Feuille cordée (igname?)", "url": "https://botapreneucourse.netlify.app/patterns-feuilles-handoff/app/images/FE-115.jpg", "named": false, "ost": "a_identifier"}]'::jsonb) as t(fe text,fam text,nom text,url text,named boolean,ost text);
insert into plant_patterns.media(code,original_name,storage_large,organ_id,caption_fr,author,license,publication_status)
 select 'PP-MED-2'||lpad(split_part(fe,'-',2),5,'0'), fe||'.jpg', url,(select id from plant_patterns.organs where code='feuille'),nom,'William Cinéa','© William Cinéa','published' from _l on conflict (code) do nothing;
insert into plant_patterns.observations(code,organ_id,status)
 select 'PP-OBS-2'||lpad(split_part(fe,'-',2),5,'0'),(select id from plant_patterns.organs where code='feuille'),ost from _l on conflict (code) do nothing;
insert into plant_patterns.evidence(media_id,observation_id)
 select m.id,o.id from _l l join plant_patterns.media m on m.code='PP-MED-2'||lpad(split_part(l.fe,'-',2),5,'0') join plant_patterns.observations o on o.code='PP-OBS-2'||lpad(split_part(l.fe,'-',2),5,'0');
insert into plant_patterns.identification_proposals(observation_id,proposed_family,author,confidence,status)
 select o.id,l.fam,'William Cinéa','forte','validee' from _l l join plant_patterns.observations o on o.code='PP-OBS-2'||lpad(split_part(l.fe,'-',2),5,'0') where l.named;
insert into plant_patterns.media_projects(media_id,project)
 select m.id,'plant_patterns' from _l l join plant_patterns.media m on m.code='PP-MED-2'||lpad(split_part(l.fe,'-',2),5,'0') on conflict do nothing;
drop table _l;;
